body { background-color: var(--gamer-bg); color: var(--gamer-text); font-family: var(--font-main); -webkit-font-smoothing: antialiased; transition: background-color 0.3s ease, color 0.3s ease; }

h1, h2, h3, h4, h5, h6, .oswald-font { font-family: var(--font-display); text-transform: uppercase; letter-spacing: 0.5px; }

a { color: var(--gamer-primary); text-decoration: none; transition: all 0.3s ease; }

a:hover { color: var(--gamer-secondary); }

/* Ripple Effect (achado de qualidade: o JS real já criava .ripple-effect
   via createElement, mas nunca existia regra CSS pra ele no arquivo
   original — efeito ficava invisível; adicionado aqui). */
.btn, .nav-link, .dropdown-item { position: relative !important; overflow: hidden !important; }
.ripple-effect {
  position: absolute;
  background: rgba(255, 255, 255, 0.4);
  transform: translate(-50%, -50%);
  pointer-events: none;
  border-radius: 50%;
  animation: ripple-animation 0.6s linear;
}
@keyframes ripple-animation {
  from { width: 0px; height: 0px; opacity: 0.5; }
  to { width: 500px; height: 500px; opacity: 0; }
}

header .navbar { background-color: var(--gamer-surface); border-bottom: 2px solid var(--gamer-border); padding: 15px 0; }

.navbar-brand-wrapper .navbar-brand-text { font-family: var(--font-display); font-size: 2rem; color: var(--gamer-text); margin: 0; }

.navbar-nav .nav-link { font-family: var(--font-display); font-size: 1.1rem; color: var(--gamer-text); padding: 10px 15px !important; }

.navbar-nav .nav-link:hover { color: var(--gamer-primary); }

.post-body-content blockquote {
  position: relative;
  background: linear-gradient(90deg, rgba(220, 38, 38, 0.08) 0%, transparent 100%);
  border-left: 4px solid #dc2626;
  padding: 1.5rem 2rem;
  margin: 2rem 0;
  font-size: 1.2rem;
  font-style: italic;
  color: var(--gamer-text);
  border-radius: 0 8px 8px 0;
  box-shadow: inset 4px 0 10px -5px rgba(220, 38, 38, 0.2);
  z-index: 1;
}

.post-body-content blockquote::before {
  content: '\201C';
  font-family: var(--font-display);
  font-size: 6rem;
  position: absolute;
  left: 10px;
  top: -20px;
  color: #dc2626;
  opacity: 0.15;
  line-height: 1;
  z-index: -1;
}

[data-bs-theme="dark"] .post-body-content blockquote {
  background: linear-gradient(90deg, rgba(239, 68, 68, 0.15) 0%, transparent 100%);
}

.game-card {
  background-color: var(--gamer-surface);
  border: 1px solid var(--gamer-border);
  border-radius: 12px;
  overflow: hidden;
  transition: all 0.3s ease;
  height: 100%;
}

.game-card:hover {
  transform: translateY(-5px);
  border-color: var(--gamer-primary);
  box-shadow: 0 10px 25px rgba(139, 92, 246, 0.15);
}

.game-cover { position: relative; aspect-ratio: 16/9; overflow: hidden; background: #000; }
.game-cover img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; opacity: 0.9; }
.game-card:hover .game-cover img { transform: scale(1.05); opacity: 1; }

.game-badge {
  position: absolute; top: 12px; left: 12px;
  background: linear-gradient(45deg, var(--gamer-primary), var(--gamer-secondary));
  color: #fff; font-family: var(--font-display); font-size: 0.8rem;
  padding: 4px 12px; border-radius: 20px; z-index: 2;
}

.animate-up { opacity: 0; transform: translateY(20px); transition: 0.5s ease; }

.animate-up.visible { opacity: 1; transform: translateY(0); }

footer { background-color: #020617; color: #94a3b8; border-top: 4px solid var(--gamer-primary); padding-top: 3rem; }

.contact-form-widget .form-control { background-color: rgba(255,255,255,0.05) !important; border: 1px solid rgba(255,255,255,0.1) !important; color: #ffffff !important; border-radius: 8px; }

.contact-form-widget .form-control:focus { border-color: var(--gamer-primary) !important; box-shadow: 0 0 0 0.25rem rgba(139,92,246,0.25) !important; }

.contact-form-button { background: linear-gradient(45deg, var(--gamer-primary), var(--gamer-secondary)); border: none !important; color: white !important; font-family: var(--font-display); font-size: 1.1rem; border-radius: 8px; padding: 10px 0; width: 100%; cursor: pointer;}

.error-404-wrapper {
  min-height: 55vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  background-color: var(--gamer-surface);
  border: 2px solid var(--gamer-border);
  border-radius: 12px;
  margin: 3rem auto;
  padding: 4rem 2rem;
  max-width: 800px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.1);
  position: relative;
  overflow: hidden;
}

.error-404-wrapper::before {
  content: ''; position: absolute; top: -50%; left: -50%; width: 200%; height: 200%;
  background: radial-gradient(circle, rgba(var(--sl-primary-rgb),0.05) 0%, transparent 60%);
  pointer-events: none; z-index: 0;
}

.error-code {
  font-size: clamp(6rem, 15vw, 10rem);
  color: var(--gamer-primary);
  text-shadow: 5px 5px 0 rgba(6, 182, 212, 0.4);
  line-height: 1;
  margin-bottom: 0;
  position: relative;
  z-index: 1;
}

.error-icon i {
  color: var(--gamer-secondary);
  font-size: 5rem;
  filter: drop-shadow(0 0 15px rgba(6, 182, 212, 0.5));
  position: relative;
  z-index: 1;
}

.error-content { position: relative; z-index: 1; }

.btn-respawn {
  background: linear-gradient(45deg, var(--gamer-primary), var(--gamer-secondary));
  color: #fff !important;
  border: none;
  font-family: var(--font-display);
  letter-spacing: 1px;
  text-transform: uppercase;
  padding: 12px 35px;
  border-radius: 30px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.btn-respawn:hover {
  transform: scale(1.05);
  box-shadow: 0 8px 25px rgba(var(--sl-primary-rgb),0.4);
}

[data-bs-theme="dark"] .error-404-wrapper {
  box-shadow: 0 10px 30px rgba(0,0,0,0.4);
}

.list-label-widget-content ul {
  list-style: none !important;
  padding: 0 !important;
  margin: 0 !important;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.list-label-widget-content ul li {
  display: inline-flex;
  align-items: center;
  margin: 0;
}

.list-label-widget-content ul li a,
.post-bottom-tags a {
  display: inline-flex;
  align-items: center;
  background: var(--gamer-surface);
  color: var(--gamer-text);
  font-family: var(--font-display);
  font-size: 0.9rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 8px 20px;
  border-radius: 4px;
  border: 1px solid var(--gamer-border);
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  text-decoration: none !important;
  box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}

.list-label-widget-content ul li a::before,
.post-bottom-tags a::before {
  content: '\F325';
  font-family: 'bootstrap-icons';
  margin-right: 8px;
  font-size: 1rem;
  color: var(--gamer-primary);
  transition: color 0.3s ease;
}

.list-label-widget-content ul li a:hover,
.post-bottom-tags a:hover {
  background: var(--gamer-primary);
  color: #ffffff !important;
  border-color: var(--gamer-primary);
  transform: translateY(-3px);
  box-shadow: 0 8px 20px rgba(var(--sl-primary-rgb),0.4);
}

.list-label-widget-content ul li a:hover::before,
.post-bottom-tags a:hover::before { color: #ffffff; }

.list-label-widget-content ul li span[dir='ltr'] {
  background: var(--gamer-secondary);
  color: #ffffff;
  font-family: var(--font-display);
  font-size: 0.8rem;
  padding: 2px 8px;
  border-radius: 4px;
  margin-left: -12px;
  font-weight: 700;
  z-index: 2;
  border: 2px solid var(--gamer-bg);
  box-shadow: 0 2px 5px rgba(0,0,0,0.3);
}

.popular-posts .item-thumbnail {
  flex-shrink: 0;
  margin-right: 15px;
}

.popular-posts .item-thumbnail img {
  width: 100px;
  height: 56px;
  object-fit: cover;
  border-radius: 8px;
  display: block;
  transition: all 0.3s ease;
}

@media (min-width: 768px) {
  .popular-posts .item-thumbnail img {
    width: 150px;
    height: 85px;
  }
}

